t = int(input())

for tc in range(t):
    n, k = map(int, input().split())

    cards = list(map(int, input().split()))
    ct = {}

    ans = n

    for c in cards:
        if c in ct:
            ct.update({c: ct[c] + 1})
        else:
            ct.update({c: 1})
        if ct[c] >= k:
            ans = k - 1

    print(ans)
